import{_ as s,c as n,o as p,a5 as e}from"./chunks/framework.DorIfSpC.js";const g=JSON.parse('{"title":"從零理解神經網路（四）：反向傳播——誰該為錯誤負責？","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/learning/micrograd_visualize/04-backpropagation"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/learning/micrograd_visualize/04-backpropagation"}],["meta",{"property":"og:title","content":"從零理解神經網路（四）：反向傳播——誰該為錯誤負責？ | 星智未來"}],["meta",{"name":"twitter:title","content":"從零理解神經網路（四）：反向傳播——誰該為錯誤負責？ | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從零理解神經網路（四）：反向傳播——誰該為錯誤負責？\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/04-backpropagation\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/04-backpropagation\\"}}"]]},"headers":[],"relativePath":"learning/micrograd_visualize/04-backpropagation.md","filePath":"learning/micrograd_visualize/04-backpropagation.md","lastUpdated":1787542547000}'),t={name:"learning/micrograd_visualize/04-backpropagation.md"};function l(i,a,o,c,r,d){return p(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="從零理解神經網路-四-反向傳播——誰該為錯誤負責" tabindex="-1">從零理解神經網路（四）：反向傳播——誰該為錯誤負責？ <a class="header-anchor" href="#從零理解神經網路-四-反向傳播——誰該為錯誤負責" aria-label="Permalink to &quot;從零理解神經網路（四）：反向傳播——誰該為錯誤負責？&quot;">​</a></h1><blockquote><p>本文是「從零理解神經網路」系列的第四篇。上一篇我們學了梯度下降，但還有一個問題：梯度怎麼算？這篇用「傳話遊戲」來解釋深度學習最核心的算法——反向傳播。</p></blockquote><h2 id="問題-梯度怎麼算" tabindex="-1">問題：梯度怎麼算？ <a class="header-anchor" href="#問題-梯度怎麼算" aria-label="Permalink to &quot;問題：梯度怎麼算？&quot;">​</a></h2><p>上一篇我們知道，更新權重需要梯度：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>w_new = w_old - η × ∂L/∂w</span></span></code></pre></div><p>這個 ∂L/∂w 就是「損失對權重 w 的偏導數」，也就是「如果我稍微調整 w，損失會變化多少」。</p><p>但神經網路可能有<strong>數百萬個權重</strong>，難道要一個一個手動算偏導數？</p><p><strong>反向傳播（Backpropagation）</strong> 就是解決這個問題的算法。它能<strong>自動且高效</strong>地計算所有權重的梯度。</p><h2 id="傳話遊戲比喻" tabindex="-1">傳話遊戲比喻 <a class="header-anchor" href="#傳話遊戲比喻" aria-label="Permalink to &quot;傳話遊戲比喻&quot;">​</a></h2><p>讓我們用一個大家都玩過的遊戲來理解反向傳播。</p><h3 id="場景設定" tabindex="-1">場景設定 <a class="header-anchor" href="#場景設定" aria-label="Permalink to &quot;場景設定&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始訊息：「6」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>傳遞過程：</span></span>
<span class="line"><span>小明 ──→ 小華 ──→ 小美 ──→ 最終輸出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每個人會把聽到的數字乘上自己的「係數」：</span></span>
<span class="line"><span>- 小明的係數：0.5</span></span>
<span class="line"><span>- 小華的係數：0.8  </span></span>
<span class="line"><span>- 小美的係數：0.3</span></span></code></pre></div><h3 id="前向傳播-forward-pass" tabindex="-1">前向傳播（Forward Pass） <a class="header-anchor" href="#前向傳播-forward-pass" aria-label="Permalink to &quot;前向傳播（Forward Pass）&quot;">​</a></h3><p>訊息從左到右傳遞：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始：6</span></span>
<span class="line"><span>  ↓ × 0.5</span></span>
<span class="line"><span>小明傳出：3</span></span>
<span class="line"><span>  ↓ × 0.8</span></span>
<span class="line"><span>小華傳出：2.4</span></span>
<span class="line"><span>  ↓ × 0.3</span></span>
<span class="line"><span>小美傳出：0.72（最終輸出）</span></span></code></pre></div><p><strong>最終輸出是 0.72，但目標是 6。差太多了！</strong></p><p>這就是「前向傳播」——資料從輸入流向輸出。</p><h3 id="發現錯誤" tabindex="-1">發現錯誤 <a class="header-anchor" href="#發現錯誤" aria-label="Permalink to &quot;發現錯誤&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目標：6</span></span>
<span class="line"><span>輸出：0.72</span></span>
<span class="line"><span>誤差：6 - 0.72 = 5.28（差了這麼多！）</span></span></code></pre></div><h3 id="反向追查-誰該負責" tabindex="-1">反向追查：誰該負責？ <a class="header-anchor" href="#反向追查-誰該負責" aria-label="Permalink to &quot;反向追查：誰該負責？&quot;">​</a></h3><p>現在要回答一個關鍵問題：<strong>這個錯誤，每個人該負多少責任？</strong></p><p>這就需要「反向傳播」——從輸出往回追溯。</p><p><strong>核心工具：鏈式法則（Chain Rule）</strong></p><p>假設損失 L 對最終輸出的梯度是 ∂L/∂output，我們要算 L 對每個係數的梯度。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ∂L</span></span>
<span class="line"><span>                  ──</span></span>
<span class="line"><span>                ∂小美係數</span></span>
<span class="line"><span></span></span>
<span class="line"><span>從輸出往回算：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>∂L         ∂L        ∂output</span></span>
<span class="line"><span>────── = ────── × ──────────</span></span>
<span class="line"><span>∂小美係數   ∂output   ∂小美係數</span></span>
<span class="line"><span></span></span>
<span class="line"><span>         ↑            ↑</span></span>
<span class="line"><span>      上一層傳來    這一層的貢獻</span></span>
<span class="line"><span>      的梯度        （小美的輸入值）</span></span></code></pre></div><h3 id="具體計算" tabindex="-1">具體計算 <a class="header-anchor" href="#具體計算" aria-label="Permalink to &quot;具體計算&quot;">​</a></h3><p>假設我們用 MSE 損失：L = ½(target - output)²</p><p><strong>Step 1：輸出層的梯度</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>∂L/∂output = -(target - output) = -(6 - 0.72) = -5.28</span></span></code></pre></div><p><strong>Step 2：小美的責任（第三層）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>∂L/∂w₃ = ∂L/∂output × ∂output/∂w₃</span></span>
<span class="line"><span>       = -5.28 × 2.4（小美的輸入）</span></span>
<span class="line"><span>       = -12.67</span></span></code></pre></div><p><strong>Step 3：把梯度傳回去</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>∂L/∂(小美的輸入) = ∂L/∂output × w₃</span></span>
<span class="line"><span>                 = -5.28 × 0.3</span></span>
<span class="line"><span>                 = -1.58</span></span></code></pre></div><p><strong>Step 4：小華的責任（第二層）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>∂L/∂w₂ = ∂L/∂(小美的輸入) × ∂(小美的輸入)/∂w₂</span></span>
<span class="line"><span>       = -1.58 × 3（小華的輸入）</span></span>
<span class="line"><span>       = -4.75</span></span></code></pre></div><p><strong>Step 5：繼續往回傳...</strong></p><p>以此類推，我們可以算出每一層的梯度。</p><h3 id="責任分配結果" tabindex="-1">責任分配結果 <a class="header-anchor" href="#責任分配結果" aria-label="Permalink to &quot;責任分配結果&quot;">​</a></h3><p>假設計算完成後：</p><table tabindex="0"><thead><tr><th style="text-align:center;">層</th><th style="text-align:center;">梯度（責任）</th><th style="text-align:center;">責任比例</th></tr></thead><tbody><tr><td style="text-align:center;">小明 (w₁)</td><td style="text-align:center;">-2.54</td><td style="text-align:center;">20%</td></tr><tr><td style="text-align:center;">小華 (w₂)</td><td style="text-align:center;">-4.75</td><td style="text-align:center;">37%</td></tr><tr><td style="text-align:center;">小美 (w₃)</td><td style="text-align:center;">-12.67</td><td style="text-align:center;">43%</td></tr></tbody></table><p><strong>小美的責任最大！因為她是最後一關，對輸出的影響最直接。</strong></p><h2 id="鏈式法則-反向傳播的數學基礎" tabindex="-1">鏈式法則：反向傳播的數學基礎 <a class="header-anchor" href="#鏈式法則-反向傳播的數學基礎" aria-label="Permalink to &quot;鏈式法則：反向傳播的數學基礎&quot;">​</a></h2><p>反向傳播的核心就是微積分的<strong>鏈式法則</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果 y = f(g(x))，則 dy/dx = dy/dg × dg/dx</span></span></code></pre></div><p>對於多層網路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L = L(a₃(a₂(a₁(x))))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>∂L/∂w₁ = ∂L/∂a₃ × ∂a₃/∂a₂ × ∂a₂/∂a₁ × ∂a₁/∂w₁</span></span>
<span class="line"><span>         ↑         ↑         ↑         ↑</span></span>
<span class="line"><span>        第3層     第3層     第2層     第1層</span></span>
<span class="line"><span>        梯度      對第2層   對第1層   對w₁</span></span>
<span class="line"><span>                 的導數    的導數    的導數</span></span></code></pre></div><p><strong>關鍵洞見</strong>：每一層只需要知道「上一層傳來的梯度」和「自己的局部導數」，就能算出「該傳給下一層的梯度」。</p><p>這就是為什麼反向傳播如此高效——它是一個<strong>局部計算</strong>的組合。</p><h2 id="完整的訓練流程" tabindex="-1">完整的訓練流程 <a class="header-anchor" href="#完整的訓練流程" aria-label="Permalink to &quot;完整的訓練流程&quot;">​</a></h2><p>現在讓我們把前向傳播和反向傳播組合起來：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    一次訓練迭代                        │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ① 前向傳播（Forward Pass）                           │</span></span>
<span class="line"><span>│     輸入 ──→ 第1層 ──→ 第2層 ──→ 第3層 ──→ 輸出       │</span></span>
<span class="line"><span>│                                        ↓             │</span></span>
<span class="line"><span>│                                     計算損失          │</span></span>
<span class="line"><span>│                                        ↓             │</span></span>
<span class="line"><span>│  ② 反向傳播（Backward Pass）                          │</span></span>
<span class="line"><span>│     ∂L/∂w₁ ←── ∂L/∂w₂ ←── ∂L/∂w₃ ←── ∂L/∂output    │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ③ 更新權重（Gradient Descent）                       │</span></span>
<span class="line"><span>│     w₁ = w₁ - η × ∂L/∂w₁                            │</span></span>
<span class="line"><span>│     w₂ = w₂ - η × ∂L/∂w₂                            │</span></span>
<span class="line"><span>│     w₃ = w₃ - η × ∂L/∂w₃                            │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                          ↓</span></span>
<span class="line"><span>                    重複很多次</span></span></code></pre></div><h2 id="反向傳播的細節" tabindex="-1">反向傳播的細節 <a class="header-anchor" href="#反向傳播的細節" aria-label="Permalink to &quot;反向傳播的細節&quot;">​</a></h2><h3 id="不同運算的局部導數" tabindex="-1">不同運算的局部導數 <a class="header-anchor" href="#不同運算的局部導數" aria-label="Permalink to &quot;不同運算的局部導數&quot;">​</a></h3><p>每種運算都有對應的局部導數規則：</p><p><strong>加法</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c = a + b</span></span>
<span class="line"><span>∂c/∂a = 1, ∂c/∂b = 1</span></span>
<span class="line"><span>梯度「平均分配」給兩個輸入</span></span></code></pre></div><p><strong>乘法</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c = a × b</span></span>
<span class="line"><span>∂c/∂a = b, ∂c/∂b = a</span></span>
<span class="line"><span>梯度「交叉傳遞」</span></span></code></pre></div><p><strong>ReLU</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y = max(0, x)</span></span>
<span class="line"><span>∂y/∂x = 1 if x &gt; 0 else 0</span></span>
<span class="line"><span>正數時梯度通過，負數時梯度被「關閉」</span></span></code></pre></div><p><strong>Tanh</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y = tanh(x)</span></span>
<span class="line"><span>∂y/∂x = 1 - tanh²(x) = 1 - y²</span></span></code></pre></div><p><strong>Sigmoid</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y = σ(x)</span></span>
<span class="line"><span>∂y/∂x = σ(x) × (1 - σ(x)) = y × (1 - y)</span></span></code></pre></div><h3 id="梯度累加" tabindex="-1">梯度累加 <a class="header-anchor" href="#梯度累加" aria-label="Permalink to &quot;梯度累加&quot;">​</a></h3><p>如果一個節點被多個運算使用，它的梯度要<strong>累加</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    a ──→ b</span></span>
<span class="line"><span>     ↘   ↗</span></span>
<span class="line"><span>       c</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果 a 同時影響 b 和 c，則：</span></span>
<span class="line"><span>∂L/∂a = ∂L/∂b × ∂b/∂a + ∂L/∂c × ∂c/∂a</span></span></code></pre></div><p>這就是為什麼 micrograd 中用 <code>grad +=</code> 而不是 <code>grad =</code>。</p><h2 id="為什麼反向傳播很厲害" tabindex="-1">為什麼反向傳播很厲害？ <a class="header-anchor" href="#為什麼反向傳播很厲害" aria-label="Permalink to &quot;為什麼反向傳播很厲害？&quot;">​</a></h2><h3 id="計算效率" tabindex="-1">計算效率 <a class="header-anchor" href="#計算效率" aria-label="Permalink to &quot;計算效率&quot;">​</a></h3><p>假設網路有 N 個權重。</p><p><strong>暴力方法</strong>：</p><ul><li>對每個權重，微調一點點，看損失變化多少</li><li>需要 N 次前向傳播</li><li>時間複雜度 O(N × 前向傳播時間)</li></ul><p><strong>反向傳播</strong>：</p><ul><li>一次前向傳播 + 一次反向傳播</li><li>反向傳播的時間約等於前向傳播</li><li>時間複雜度 O(2 × 前向傳播時間)</li></ul><p>對於有數百萬參數的網路，反向傳播<strong>快了數百萬倍</strong>！</p><h3 id="模組化" tabindex="-1">模組化 <a class="header-anchor" href="#模組化" aria-label="Permalink to &quot;模組化&quot;">​</a></h3><p>每一層只需要實現：</p><ol><li><code>forward()</code>：前向傳播</li><li><code>backward()</code>：計算局部梯度並傳遞</li></ol><p>這讓我們可以像樂高一樣組合不同的層，自動微分框架會處理所有梯度計算。</p><h2 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h2><h3 id="梯度消失-vanishing-gradient" tabindex="-1">梯度消失（Vanishing Gradient） <a class="header-anchor" href="#梯度消失-vanishing-gradient" aria-label="Permalink to &quot;梯度消失（Vanishing Gradient）&quot;">​</a></h3><p>當網路很深時，梯度可能在傳遞過程中越來越小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假設每層的局部梯度都是 0.25（Sigmoid 的最大值）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10 層後：0.25^10 ≈ 0.000001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>梯度幾乎消失，淺層學不動！</span></span></code></pre></div><p><strong>解決方案</strong>：</p><ul><li>使用 ReLU（梯度是 0 或 1）</li><li>使用殘差連接（ResNet）</li><li>使用 BatchNorm</li></ul><h3 id="梯度爆炸-exploding-gradient" tabindex="-1">梯度爆炸（Exploding Gradient） <a class="header-anchor" href="#梯度爆炸-exploding-gradient" aria-label="Permalink to &quot;梯度爆炸（Exploding Gradient）&quot;">​</a></h3><p>相反地，梯度也可能越來越大：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果每層的局部梯度都是 4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10 層後：4^10 ≈ 1,000,000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>梯度爆炸，參數更新太劇烈！</span></span></code></pre></div><p><strong>解決方案</strong>：</p><ul><li>梯度裁剪（Gradient Clipping）</li><li>適當的權重初始化</li><li>使用 BatchNorm</li></ul><h2 id="互動視覺化" tabindex="-1">互動視覺化 <a class="header-anchor" href="#互動視覺化" aria-label="Permalink to &quot;互動視覺化&quot;">​</a></h2><p>我製作了一個互動工具，讓你可以：</p><ul><li>觀察三層網路的前向傳播和反向傳播</li><li>看每一層的「責任」分配</li><li>調整權重和學習率，觀察訓練過程</li><li>追蹤詳細的梯度計算</li></ul><p>👉 <a href="/htmls/backprop-complete.html" target="_blank">反向傳播互動視覺化</a></p><p>建議你操作時注意：</p><ol><li>反向傳播時，梯度如何從輸出層往回傳</li><li>每層的「責任」（梯度）比例</li><li>更新後，損失如何下降</li></ol><h2 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to &quot;小結&quot;">​</a></h2><p>今天我們學到了：</p><ol><li><strong>反向傳播</strong>是高效計算梯度的算法</li><li>用<strong>傳話遊戲</strong>理解：從錯誤往回追，分配責任</li><li><strong>鏈式法則</strong>是數學基礎：∂L/∂w = ∂L/∂output × ∂output/∂...× ∂.../∂w</li><li>每層只需要知道「上層梯度」和「局部導數」</li><li>梯度要<strong>累加</strong>（一個節點可能影響多個輸出）</li><li>反向傳播比暴力方法<strong>快數百萬倍</strong></li><li>注意<strong>梯度消失</strong>和<strong>梯度爆炸</strong>問題</li></ol><h2 id="下一篇預告" tabindex="-1">下一篇預告 <a class="header-anchor" href="#下一篇預告" aria-label="Permalink to &quot;下一篇預告&quot;">​</a></h2><p>反向傳播需要追蹤每個運算的依賴關係。這是怎麼做到的？</p><p>下一篇我們會介紹<strong>計算圖（Computational Graph）</strong>——深度學習框架（如 PyTorch）的核心數據結構。我們會實際看看 micrograd 如何用幾十行程式碼實現「自動微分」。</p><hr><p><em>本文是「從零理解神經網路」系列的第四篇。如果你覺得有幫助，歡迎分享給也在學習 ML 的朋友。</em></p>`,105)])])}const u=s(t,[["render",l]]);export{g as __pageData,u as default};
